function minSwaps(s) {
  let ones = 0;
  for (const ch of s) {
    if (ch === '1') {
      ones++;
    }
  }
  const zeros = s.length - ones;
  if (Math.abs(ones - zeros) > 1) {
    return -1;
  }

  let wrongZeroFirst = 0;
  for (let i = 0; i < s.length; i++) {
    const want = i % 2 === 0 ? '0' : '1';
    if (s[i] !== want) {
      wrongZeroFirst++;
    }
  }
  const wrongOneFirst = s.length - wrongZeroFirst;

  if (zeros > ones) {
    return wrongZeroFirst / 2;
  }
  if (ones > zeros) {
    return wrongOneFirst / 2;
  }
  return Math.min(wrongZeroFirst, wrongOneFirst) / 2;
}

