function minSwaps(s) {
  // Breadth-first search over every string reachable by swaps.
  const isAlternating = (t) => { for (let i = 1; i < t.length; i++) if (t[i] === t[i - 1]) return false; return true; };
  const dist = new Map([[s, 0]]);
  const queue = [s];
  for (let head = 0; head < queue.length; head++) {
    const cur = queue[head];
    if (isAlternating(cur)) return dist.get(cur);
    for (let i = 0; i < cur.length; i++) {
      for (let j = i + 1; j < cur.length; j++) {
        if (cur[i] === cur[j]) continue;
        const chars = cur.split('');
        [chars[i], chars[j]] = [chars[j], chars[i]];
        const next = chars.join('');
        if (!dist.has(next)) { dist.set(next, dist.get(cur) + 1); queue.push(next); }
      }
    }
  }
  return -1;
}

