function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(990, 1000) : int(1, 10);
  const roll = rand();
  if (roll < 0.2) {
    // Fully random bits: often impossible.
    let text = '';
    for (let i = 0; i < n; i++) text += rand() < 0.5 ? '0' : '1';
    return [text];
  }
  // Balanced counts (differing by at most one), shuffled.
  let ones = Math.floor(n / 2);
  if (n % 2 === 1 && rand() < 0.5) ones++;
  if (roll > 0.9 && n > 2) ones += rand() < 0.5 ? 2 : -2;
  ones = Math.max(0, Math.min(n, ones));
  const chars = [];
  for (let i = 0; i < n; i++) chars.push(i < ones ? '1' : '0');
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
